local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local function b64decode(data)
    data = data:gsub("[^%w%+/=]", "")
    local ok, res = pcall(function()
        if crypt and crypt.base64decode then return crypt.base64decode(data) end
        if crypt and crypt.base64 and crypt.base64.decode then return crypt.base64.decode(data) end
        if base64decode then return base64decode(data) end
        if base64_decode then return base64_decode(data) end
        error("sin decoder nativo")
    end)
    if ok and res then return res end
    local rev = {}
    for i = 1, 64 do rev[B64:sub(i, i)] = i - 1 end
    local out, n = {}, 0
    for i = 1, #data, 4 do
        local a, b = rev[data:sub(i, i)], rev[data:sub(i + 1, i + 1)]
        local c, d = rev[data:sub(i + 2, i + 2)], rev[data:sub(i + 3, i + 3)]
        local v = a * 262144 + b * 4096 + (c or 0) * 64 + (d or 0)
        n = n + 1
        if not c then
            out[n] = string.char(math.floor(v / 65536))
        elseif not d then
            out[n] = string.char(math.floor(v / 65536), math.floor(v / 256) % 256)
        else
            out[n] = string.char(math.floor(v / 65536), math.floor(v / 256) % 256, v % 256)
        end
    end
    return table.concat(out)
end

local function saveOnce(folder, name, b64)
    local path = folder .. "/" .. name
    if isfile and isfile(path) then return end
    pcall(function()
        if makefolder then
            for _, f in ipairs({BASE, BASE .. "/Content", folder}) do
                if not (isfolder and isfolder(f)) then pcall(makefolder, f) end
            end
        end
        writefile(path, b64decode(b64))
    end)
end

saveOnce(ANIMS,  ANIM_NAME,  ANIM_B64)
saveOnce(SOUNDS, SOUND_NAME, SOUND_B64)
ANIM_B64, SOUND_B64 = nil, nil

table.insert(modules, function()
    local m = {}
    m.ModuleType  = "DANCE"
    m.Name        = "WRONG NUMBA"
    m.Description = "sl5✌️🫩 by Mrclown"
    m.Assets = {ANIM_NAME, SOUND_NAME}
    m.Config = function(parent)
        Util_CreateText(parent, "No settings.", 14, Enum.TextXAlignment.Center)
    end
    m.SaveConfig = function() return {} end
    m.LoadConfig  = function(save) end
    local animator = nil
    local start    = 0
    m.Init = function(figure)
        SetOverrideDanceMusic(AssetGetContentId(SOUND_NAME), "PlaceHolder", 0.8, NumberRange.new(0, 999))
        start           = os.clock()
        animator        = AnimLib.Animator.new()
        animator.rig    = figure
        animator.track  = AnimLib.Track.fromfile(AssetGetPathFromFilename(ANIM_NAME))
        animator.looped = true
        animator.speed  = 1
    end
    local DURATION = 31.01
    m.Update = function(dt, figure)
        local elapsed = os.clock() - start
        if elapsed >= DURATION then
            start   = os.clock()
            elapsed = 0
            SetOverrideDanceMusic(AssetGetContentId(SOUND_NAME), "PlaceHolder", 0.8, NumberRange.new(0, 999))
        end
        animator:Step(elapsed)
    end
    m.Destroy = function(figure)
        animator = nil
    end
    return m
end)
return modules
